// --- Coach Brain (Code node, AI Coach) ---
// Model proposes (intent + item + amount), code decides (verdict + numbers).
// mergeUserTxns() and affordability() are exact copies of the Main workflow's
// "Merge User & Txns" and "Affordability Algorithm" nodes. Update both together.
// Mode: Run Once for All Items.
const INTENTS = new Set(['afford', 'spending', 'goals', 'balance', 'general'])
const MAX_QUESTION = 500

// Python-style rounding (half to even), so amounts match the earlier Python version exactly.
function pyRound(value) {
  const floor = Math.floor(value)
  const diff = value - floor
  if (diff > 0.5) return floor + 1
  if (diff < 0.5) return floor
  return floor % 2 === 0 ? floor : floor + 1
}

// Mauritius time: UTC+4, no daylight saving.
function mauritiusNow(offsetDays = 0) {
  const shifted = new Date(Date.now() + 4 * 3600e3 + offsetDays * 86400e3).toISOString()
  return { date: shifted.slice(0, 10), stamp: shifted.slice(0, 19) + '+04:00' }
}

function mergeUserTxns(items) {
  const $input = { first: () => items[0], all: () => items }
  // --- Merge User & Txns (Code node) ---
  // Input comes from the "Get User & Txns" aggregate: one item with
  // profile[], transactions[] and the original request. Mode: Run Once for All Items.


  // --- Input ---
  const aggregateItem = $input.first().json
  const request = aggregateItem.request || {}
  const profileRows = aggregateItem.profile || []
  const userProfile = profileRows.length ? profileRows[0] : {}

  // A Firebase account exists before any Mongo profile does, so check for one.
  const profileComplete = Object.keys(userProfile).length > 0 && userProfile.salary !== undefined && userProfile.salary !== null

  const targetCents = request.targetAmountCents !== undefined ? request.targetAmountCents : request.targetAmount
  const intent = request.intent || request.inputType || null

  // --- Output: the exact shape the Affordability Algorithm expects ---
  return [{ json: {
    userId: aggregateItem.userId,
    user: userProfile,
    transactions: aggregateItem.transactions || [],
    targetAmountCents: Math.trunc(Number(targetCents || 0)),
    intent,
    itemName: request.itemName ?? null,
    link: request.link ?? null,
    goalType: request.goalType || (request.itemName ? 'product' : 'cash'),
    goalKey: request.goalKey ?? null,
    savedAmountCents: Math.trunc(Number(request.savedAmountCents || 0)),
    profileComplete,
    today: mauritiusNow().date,
  } }]
}

function affordability(items) {
  const $input = { first: () => items[0], all: () => items }
  // --- Affordability Algorithm (Code node) ---
  // Mode: Run Once for All Items. All amounts are integer cents.

  // --- Config (team-tuned spike weights, integer cents) ---
  const MAX_MONTHS = 120
  const FESTIVAL_SPIKE_CENTS = {
    "New Year's Day": 400000,
    'Thaipoosam Cavadee': 400000,
    'Maha Shivaratree': 350000,
    'Chinese Spring Festival': 350000,
    'Eid-ul-Fitr': 300000,
    'Ougadi': 300000,
    'Ganesh Chaturthi': 250000,
    'Divali': 600000,
    'Christmas Day': 900000,
  }
  // Events not in the festival list, as [month, name, cents]. Add as the team decides.
  const MANUAL_EVENTS = [] // e.g. [[9, 'Pere Laval pilgrimage', 250000]]
  const RESERVE_UPCOMING_FESTIVALS = true // hold back festivals due soon
  const RESERVE_WINDOW_DAYS = 60

  // Mauritius festival dates 2024-2040, generated from the Python `holidays` library (v0.105),
// the source the earlier Python version used. Regenerate before 2029 to cover 10 years ahead.
const FESTIVAL_DATES = {
  "New Year's Day": ["2024-01-01", "2025-01-01", "2026-01-01", "2027-01-01", "2028-01-01", "2029-01-01", "2030-01-01", "2031-01-01", "2032-01-01", "2033-01-01", "2034-01-01", "2035-01-01", "2036-01-01", "2037-01-01", "2038-01-01", "2039-01-01", "2040-01-01"],
  "Thaipoosam Cavadee": ["2024-01-25", "2025-02-11", "2026-02-02", "2027-01-22", "2028-02-09", "2029-01-29", "2030-01-18", "2031-02-06", "2032-01-27", "2033-02-14", "2034-02-03", "2035-01-23", "2036-02-11", "2037-01-30", "2038-01-19", "2039-02-07", "2040-01-28"],
  "Maha Shivaratree": ["2024-03-08", "2025-02-26", "2026-02-15", "2027-03-06", "2028-02-23", "2029-02-11", "2030-03-02", "2031-02-20", "2032-03-10", "2033-02-27", "2034-02-17", "2035-03-08"],
  "Chinese Spring Festival": ["2024-02-10", "2025-01-29", "2026-02-17", "2027-02-06", "2028-01-26", "2029-02-13", "2030-02-03", "2031-01-23", "2032-02-11", "2033-01-31", "2034-02-19", "2035-02-08", "2036-01-28", "2037-02-15", "2038-02-04", "2039-01-24", "2040-02-12"],
  "Eid-ul-Fitr": ["2024-04-11", "2025-04-01", "2026-03-21", "2027-03-10", "2028-02-27", "2029-02-15", "2030-02-05", "2031-01-25", "2032-01-15", "2033-01-03", "2033-12-24", "2034-12-13", "2035-12-02", "2036-11-20", "2037-11-09", "2038-10-30", "2039-10-20", "2040-10-08"],
  "Ougadi": ["2024-04-09", "2025-03-30", "2026-03-19", "2027-04-07", "2028-03-27", "2029-04-14", "2030-04-03", "2031-03-24", "2032-04-11", "2033-03-31", "2034-03-21", "2035-04-09"],
  "Ganesh Chaturthi": ["2024-09-08", "2025-08-28", "2026-09-14", "2027-09-04", "2028-08-23", "2029-09-11", "2030-09-01", "2031-09-20", "2032-09-08", "2033-08-28", "2034-09-16", "2035-09-05"],
  "Divali": ["2024-10-31", "2025-10-20", "2026-11-08", "2027-10-29", "2028-10-17", "2029-11-05", "2030-10-26", "2031-11-14", "2033-10-22", "2034-11-10", "2035-10-30"],
  "Christmas Day": ["2024-12-25", "2025-12-25", "2026-12-25", "2027-12-25", "2028-12-25", "2029-12-25", "2030-12-25", "2031-12-25", "2032-12-25", "2033-12-25", "2034-12-25", "2035-12-25", "2036-12-25", "2037-12-25", "2038-12-25", "2039-12-25", "2040-12-25"],
}

  // --- Date helpers (ISO "YYYY-MM-DD" strings compare correctly as text) ---
  const addDays = (isoDate, days) => new Date(Date.parse(isoDate + 'T00:00:00Z') + days * 86400e3).toISOString().slice(0, 10)
  const monthKey = (year, month) => `${year}-${String(month).padStart(2, '0')}`

  // --- Input (built by Merge User & Txns) ---
  const item = $input.first().json
  const user = item.user || {}
  const txns = item.transactions || []
  const target = Math.trunc(Number(item.targetAmountCents || 0))
  const today = item.today // Mauritius date, not the server clock
  const todayYear = Number(today.slice(0, 4))
  const todayMonth = Number(today.slice(5, 7))

  const passthrough = {
    userId: item.userId,
    intent: item.intent ?? null,
    itemName: item.itemName ?? null,
    link: item.link ?? null,
    goalType: item.goalType ?? null,
    targetAmountCents: target,
    goalKey: item.goalKey ?? null,
    savedAmountCents: Math.trunc(Number(item.savedAmountCents || 0)),
  }

  // --- Guard: Firebase account exists but no financial profile yet ---
  if (!item.profileComplete) {
    return [{ json: { ...passthrough, verdict: 'NEEDS_PROFILE', monthsNeeded: 0, inferredBalance: 0, safeToSpend: 0, reachable: false } }]
  }

  // --- Step 1: inferred balance ---
  let balance = 0
  let recent = txns
  if (user.manualBalance !== undefined && user.manualBalance !== null) {
    balance = Math.trunc(Number(user.manualBalance))
    const cutoff = String(user.manualBalanceDate || '')
    recent = txns.filter((t) => String(t.txnDate) > cutoff)
  }
  for (const t of recent) {
    const amount = Math.trunc(Number(t.amount ?? 0))
    balance += t.direction === 'income' ? amount : -amount
  }

  // --- Step 2: usual monthly spending (integer cents) ---
  // The user's own monthly expense list wins; otherwise estimate from repeat expenses.
  const declaredExpenses = (user.monthlyExpenses || []).filter((e) => e && typeof e === 'object' && !Array.isArray(e))
  let monthlyRoutine
  if (declaredExpenses.length) {
    monthlyRoutine = declaredExpenses.reduce((sum, e) => sum + Math.trunc(Number(e.amountCents || 0)), 0)
  } else {
    const routine = txns.filter((t) => t.isRoutine && t.direction === 'expense')
    const monthsSeen = new Set(routine.map((t) => String(t.txnDate).slice(0, 7))).size || 1
    monthlyRoutine = Math.floor(routine.reduce((sum, t) => sum + Math.trunc(Number(t.amount ?? 0)), 0) / monthsSeen)
  }

  // --- Step 3: monthly income ---
  const monthlyIncome = Math.trunc(Number(user.salary || 0))

  // --- Step 4: festival spikes as dated events, summed per month ---
  const lastYear = todayYear + Math.floor(MAX_MONTHS / 12) + 1
  const festivalEvents = [] // [isoDate, cents]
  for (const [festival, spikeCents] of Object.entries(FESTIVAL_SPIKE_CENTS)) {
    for (const isoDate of FESTIVAL_DATES[festival] || []) {
      const year = Number(isoDate.slice(0, 4))
      if (year >= todayYear && year <= lastYear) festivalEvents.push([isoDate, spikeCents])
    }
  }
  for (let year = todayYear; year <= lastYear; year++) {
    for (const [month, , spikeCents] of MANUAL_EVENTS) festivalEvents.push([`${monthKey(year, month)}-01`, spikeCents])
  }

  const spikeByMonth = {}
  for (const [isoDate, cents] of festivalEvents) {
    const key = isoDate.slice(0, 7)
    spikeByMonth[key] = (spikeByMonth[key] || 0) + cents
  }
  const surplusFor = (year, month) => (monthlyIncome - monthlyRoutine) - (spikeByMonth[monthKey(year, month)] || 0)

  // --- Step 5: buffer + safe-to-spend now ---
  const buffer = Math.floor(monthlyRoutine * Math.trunc(Number(user.bufferWeeks || 4)) / 4)
  const safeBase = balance - buffer
  const reserveUntil = addDays(today, RESERVE_WINDOW_DAYS)
  const festivalReserve = RESERVE_UPCOMING_FESTIVALS
    ? festivalEvents.filter(([d]) => today <= d && d <= reserveUntil).reduce((sum, [, cents]) => sum + cents, 0)
    : 0
  const safeNow = safeBase - festivalReserve

  // --- Step 6: verdict / timeline ---
  let verdict
  let months = 0
  let reachable = true
  if (target <= safeNow) {
    verdict = 'SAFE'
  } else if (target <= safeNow + buffer) {
    verdict = 'TIGHT'
  } else {
    // Timeline starts from the base, then subtracts each month's spikes once.
    const thisMonth = today.slice(0, 7)
    const stillDueThisMonth = festivalEvents
      .filter(([d]) => d >= today && d.slice(0, 7) === thisMonth)
      .reduce((sum, [, cents]) => sum + cents, 0)
    verdict = 'NOT_SAFE'
    let accumulated = safeBase - stillDueThisMonth
    let year = todayYear
    let month = todayMonth
    while (accumulated < target && months < MAX_MONTHS) {
      month += 1
      if (month > 12) { month = 1; year += 1 }
      accumulated += surplusFor(year, month)
      months += 1
    }
    reachable = accumulated >= target
  }

  // --- Output: original keys plus passthrough for the goal save ---
  return [{ json: {
    ...passthrough,
    verdict,
    monthsNeeded: months,
    inferredBalance: balance,
    safeToSpend: safeNow,
    reachable,
  } }]
}

// --- Helpers ---
// "Rs 12,345" with plain commas, whatever locale the n8n server uses.
const rs = (cents) => 'Rs ' + String(pyRound((cents || 0) / 100)).replace(/\B(?=(\d{3})+(?!\d))/g, ',')

// Fallback when the intent model fails: keywords + first number.
function rulesIntent(text) {
  const low = text.toLowerCase()
  let amount = 0
  const match = low.match(/(\d[\d,]*(?:\.\d+)?)\s*(k|mil)?\b/)
  if (match) {
    amount = Number(match[1].replace(/,/g, ''))
    if (match[2]) amount *= 1000
  }
  const rules = [
    ['afford', ['afford', 'buy', 'aste', 'achet', 'kapav']],
    ['spending', ['spend', 'spent', 'depans', 'dépens']],
    ['goals', ['goal', 'objectif', 'lobzektif']],
    ['balance', ['balance', 'save', 'saving', 'lamone', 'reste']],
  ]
  for (const [intent, words] of rules) {
    if (words.some((word) => low.includes(word))) return [intent, amount, '']
  }
  return [amount ? 'afford' : 'general', amount, '']
}

// --- Input: intent output merged with the user bundle ---
const merged = $input.first().json
const request = merged.request || {}
const question = String(request.question || '').trim().slice(0, MAX_QUESTION)
const ai = merged.output && typeof merged.output === 'object' && !Array.isArray(merged.output) ? merged.output : {}
let intent = String(ai.intent || '').trim().toLowerCase()
let itemName = String(ai.itemName || '').trim()
let amountRupees = ai.amountRupees || 0
const language = ai.language || 'en'
let intentSource = 'ai'
if (!INTENTS.has(intent)) {
  [intent, amountRupees, itemName] = rulesIntent(question)
  intentSource = 'rules'
}
const rupees = Number(amountRupees)
const targetCents = Number.isFinite(rupees) ? Math.max(pyRound(rupees * 100), 0) : 0

const profileRows = merged.profile || []
const profile = profileRows.length ? profileRows[0] : {}
const txns = merged.transactions || []
const goals = merged.goals || []
let facts = {}
let verdict = null
let draft

function runAfford(cents, label) {
  const bundle = {
    userId: merged.userId ?? null, profile: profileRows, transactions: txns,
    request: { intent: 'afford', targetAmountCents: cents, itemName: label || null },
  }
  return affordability(mergeUserTxns([{ json: bundle }]))[0].json
}

// --- Overview numbers every answer can use (same rules as the Read API) ---
// The user's own monthly expense list wins; otherwise estimate from repeat expenses.
const declaredExpenses = (profile.monthlyExpenses || []).filter((e) => e && typeof e === 'object' && !Array.isArray(e))
let monthlyRoutine
if (declaredExpenses.length) {
  monthlyRoutine = declaredExpenses.reduce((sum, e) => sum + Math.trunc(Number(e.amountCents || 0)), 0)
} else {
  const routine = txns.filter((t) => t.isRoutine && t.direction === 'expense')
  const monthsSeen = new Set(routine.map((t) => String(t.txnDate).slice(0, 7))).size || 1
  monthlyRoutine = Math.floor(routine.reduce((sum, t) => sum + Math.trunc(Number(t.amount ?? 0)), 0) / monthsSeen)
}
const salary = Math.trunc(Number(profile.salary || 0))
const profileComplete = Object.keys(profile).length > 0 && profile.salary !== undefined && profile.salary !== null

// --- Decide ---
if (!question) {
  intent = 'general'
  draft = 'Ask me something like: can I buy a laptop for Rs 15,000?'
} else if (!profileComplete) {
  intent = 'needs_profile'
  verdict = 'NEEDS_PROFILE'
  draft = 'I need your monthly salary first. Add it on the Financial Overview page, then ask again.'
} else if (intent === 'afford' && targetCents <= 0) {
  draft = 'How much does it cost? Tell me the price in rupees and I will check it.'
  facts = { needs: 'price' }
} else if (intent === 'afford') {
  const result = runAfford(targetCents, itemName)
  verdict = result.verdict
  const label = itemName || 'it'
  facts = {
    item: label, price: rs(targetCents), verdict,
    safeToSpendNow: rs(result.safeToSpend), balanceNow: rs(result.inferredBalance),
    monthsNeeded: result.monthsNeeded, reachable: result.reachable,
  }
  if (verdict === 'SAFE') {
    draft = `Yes. You can buy ${label} for ${rs(targetCents)} now. You would still have about ${rs(result.safeToSpend - targetCents)} of safe money left.`
  } else if (verdict === 'TIGHT') {
    draft = `You can, but it is tight. ${rs(targetCents)} would eat into the safety buffer you keep for your usual monthly spending.`
  } else if (result.reachable) {
    draft = `Not yet. Right now you have ${rs(result.safeToSpend)} safe to spend. At your current pace you could afford ${label} in about ${result.monthsNeeded} month(s).`
  } else {
    draft = `Not with your current budget. Your usual monthly spending (${rs(monthlyRoutine)}) is close to or above your salary (${rs(salary)}), so savings do not build up.`
  }
} else if (intent === 'spending') {
  const since = mauritiusNow(-30).date
  const before = mauritiusNow(-60).date
  const thisPeriod = {}
  const lastPeriod = {}
  for (const t of txns) {
    if (t.direction !== 'expense') continue
    const day = String(t.txnDate)
    const category = t.category || 'other'
    const amount = Math.trunc(Number(t.amount || 0))
    if (day >= since) thisPeriod[category] = (thisPeriod[category] || 0) + amount
    else if (day >= before) lastPeriod[category] = (lastPeriod[category] || 0) + amount
  }
  const top = Object.entries(thisPeriod).sort((a, b) => b[1] - a[1]).slice(0, 3)
  const sum = (map) => Object.values(map).reduce((total, v) => total + v, 0)
  facts = {
    spentLast30Days: rs(sum(thisPeriod)),
    spentPrevious30Days: rs(sum(lastPeriod)),
    topCategories: Object.fromEntries(top.map(([k, v]) => [k, rs(v)])),
  }
  const biggest = Object.entries(facts.topCategories).map(([k, v]) => `${k} ${v}`).join(', ') || 'none yet'
  draft = `In the last 30 days you spent ${facts.spentLast30Days} (the 30 days before: ${facts.spentPrevious30Days}). Biggest: ${biggest}.`
} else if (intent === 'goals') {
  const rows = [...goals].sort((a, b) => {
    const keyA = String(a.updatedAt || ''), keyB = String(b.updatedAt || '')
    return keyA === keyB ? 0 : keyA < keyB ? 1 : -1
  }).slice(0, 5)
  facts = { goals: rows.map((g) => ({
    item: g.itemName || 'cash goal', target: rs(g.targetAmount), saved: rs(g.savedAmount),
    verdict: g.verdict ?? null, status: g.status ?? null, months: g.timelineMonths ?? null,
  })) }
  const describe = (g) => g.status === 'stalled' ? 'not reachable yet' : g.verdict === 'SAFE' ? 'ready now' : `about ${g.months} month(s)`
  draft = goals.length
    ? `You have ${goals.length} goal(s). ` + facts.goals.map((g) => `${g.item} (${g.target}, ${g.saved} saved): ${describe(g)}.`).join(' ')
    : 'You have no saved goals yet. Try: can I buy a laptop for Rs 15,000?'
} else {
  const base = runAfford(0, null)
  facts = {
    salary: rs(salary), usualMonthlySpending: rs(monthlyRoutine),
    monthlySurplus: rs(salary - monthlyRoutine),
    balanceNow: rs(base.inferredBalance), safeToSpendNow: rs(base.safeToSpend),
  }
  draft = `Your salary is ${facts.salary} and your usual monthly spending is ${facts.usualMonthlySpending}, so about ${facts.monthlySurplus} a month is left to save. Right now about ${facts.safeToSpendNow} is safe to spend.`
}

const writerPrompt = `LANGUAGE: ${language}\nQUESTION: ${question}\nINTENT: ${intent}\nFACTS: ${JSON.stringify(facts)}\nDRAFT ANSWER: ${draft}`

// --- Output ---
return [{ json: {
  intent, intentSource, verdict,
  itemName: itemName || null, targetAmountCents: targetCents,
  facts, draftAnswer: draft, writerPrompt,
} }]

// --- Shape Coach Reply (Code node, AI Coach) ---
// Uses the AI wording when the writer succeeded, else the code-written draft.
// Mode: Run Once for All Items.
const merged = $input.first().json
const text = merged.text
const useAi = typeof text === 'string' && text.trim() !== '' && !merged.error
return [{ json: {
  success: true,
  record: 'coach',
  intent: merged.intent ?? null,
  verdict: merged.verdict ?? null,
  answer: useAi ? text.trim() : (merged.draftAnswer ?? null),
  answerSource: useAi ? 'ai' : 'template',
  facts: merged.facts || {},
} }]
